package com.aaliyun.leadnews.admin.config;import com.aaliyun.leadnews.common.persistence.AuditMetaObjectHandler;import com.aaliyun.leadnews.common.security.JwtTokenService;import com.baomidou.mybatisplus.extension.plugins.MybatisPlusInterceptor;import com.baomidou.mybatisplus.extension.plugins.inner.OptimisticLockerInnerInterceptor;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;@Configuration public class AdminConfiguration{@Bean JwtTokenService jwtTokenService(@Value("${JWT_SECRET}")String s){return new JwtTokenService(s);}@Bean BCryptPasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}@Bean AuditMetaObjectHandler auditMetaObjectHandler(){return new AuditMetaObjectHandler();}@Bean MybatisPlusInterceptor mybatisPlusInterceptor(){MybatisPlusInterceptor i=new MybatisPlusInterceptor();i.addInnerInterceptor(new OptimisticLockerInnerInterceptor());return i;}}
